      const lexwareApiKey = (body.lexwareApiKey || "").trim();
      const resendApiKey = (body.resendApiKey || "").trim();
      const gitHubRepo = (body.gitHubRepo || "MKN1411/actanex-open").trim();
      const gitHubBranch = (body.gitHubBranch || "main").trim();
